CREATE OR REPLACE FUNCTION public.fn_member_sign_contract(p_contract_id text, p_signature text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c contracts%ROWTYPE;
BEGIN
  SELECT * INTO c FROM contracts WHERE id=p_contract_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error_code','CONTRACT.NOT_FOUND'); END IF;
  IF current_member_id() IS NULL OR c.member_id <> current_member_id() THEN
    RETURN jsonb_build_object('ok',false,'error_code','AUTH.FORBIDDEN');
  END IF;
  IF c.signed_at IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'already',true); END IF;
  IF p_signature IS NULL OR length(p_signature) < 200 THEN
    RETURN jsonb_build_object('ok',false,'error_code','SIGNATURE.INVALID');
  END IF;
  UPDATE contracts SET signature=p_signature, signed_at=now() WHERE id=c.id;
  RETURN jsonb_build_object('ok',true,'contract_id',c.id);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error_code',SQLERRM);
END $function$

CREATE OR REPLACE FUNCTION public.fn_tk_window_check(p_ticket text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t member_tickets%rowtype; v_min date; v_max date;
begin
  if p_ticket is null then return; end if;
  select * into t from member_tickets where id = p_ticket;
  if not found or not public.fn_tk_is_unopened(t) then return; end if;
  select * into t from member_tickets where id = p_ticket for update;      -- 之後的查詢是新快照，看得到對方已提交的預約
  if not found or not public.fn_tk_is_unopened(t) then return; end if;
  select min(h.bdate), max(h.bdate) into v_min, v_max from public.fn_tk_holding(p_ticket, null) h;
  if v_min is null then return; end if;
  if (v_max - v_min) > (t.valid_days - 1) then
    raise exception 'TKWIN.OUT_OF_WINDOW:%:%', to_char(v_min, 'YYYY-MM-DD'), to_char(v_min + (t.valid_days - 1), 'YYYY-MM-DD')
      using errcode = 'P0001',
            hint = '尚未啟用的票券，預約日期需落在最早一堂起 ' || t.valid_days || ' 天內（至 ' || to_char(v_min + (t.valid_days - 1), 'YYYY/MM/DD') || '）；首次簽到後才正式起算效期';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.trg_tk_quota_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_used_new integer; v_used_old integer;
begin
  if new.unlocked_sessions is null or coalesce(new.sessions_total, 0) <= 0 then return new; end if;
  if new.unlocked_sessions >= new.sessions_total then return new; end if;          -- 完整開通：沒有額度概念
  v_used_new := new.sessions_total - coalesce(new.sessions_remaining, 0);
  v_used_old := coalesce(old.sessions_total, new.sessions_total) - coalesce(old.sessions_remaining, 0);
  if v_used_new > v_used_old and v_used_new > new.unlocked_sessions then
    raise exception 'TICKET.INSTALLMENT_LOCKED'
      using errcode = 'P0001',
            detail = format('used=%s unlocked=%s', v_used_new, new.unlocked_sessions),
            hint = '分期票只能使用已開通的堂數；請先完成下一期付款開通，再預約或扣課';
  end if;
  return new;
end
$function$
